import React, { useState, useEffect } from 'react';
import { uploadFile, getFiles, downloadEncryptedFile, downloadDecryptedFile, deleteFile } from '../services/api';
import CryptoFlow from '../components/CryptoFlow';
import SciFiAlert from '../components/SciFiAlert';
import { Upload, Server, HardDrive, Terminal, Activity, Play, X, RefreshCw, FileCheck, FileText } from 'lucide-react';
import { Bar } from 'react-chartjs-2';
import { Chart as ChartJS, CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend } from 'chart.js';

ChartJS.register(CategoryScale, LinearScale, BarElement, Title, Tooltip, Legend);

const Dashboard = () => {
  const [files, setFiles] = useState([]);
  const [fileToUpload, setFileToUpload] = useState(null);
  const [uploadStep, setUploadStep] = useState(0);
  const [logs, setLogs] = useState([]);
  const [selectedFile, setSelectedFile] = useState(null);
  const [successMode, setSuccessMode] = useState(false);
  const [customAlert, setCustomAlert] = useState(null);
  const [cryptoMode, setCryptoMode] = useState('hybrid');
  const [activeTab, setActiveTab] = useState("overview");

  useEffect(() => { fetchFiles(); }, []);

  const addLog = (msg) => {
    const timestamp = new Date().toLocaleTimeString('en-US', { hour12: false });
    setLogs(prev => [`[${timestamp}] ${msg}`, ...prev]);
  };

  const fetchFiles = async () => {
    try { const res = await getFiles(); setFiles(res.data); } catch (err) {}
  };

  const resetUpload = () => {
    setFileToUpload(null);
    setSuccessMode(false);
    setUploadStep(0);
  };

  const onFileDrop = (e) => {
    const file = e.target.files[0];
    if (file) {
      setFileToUpload(file);
      setSuccessMode(false);
      addLog(`STAGE: ${file.name} loaded.`);
    }
  };

  const startEncryption = async () => {
    if (!fileToUpload) return;
    setUploadStep(1);
    setLogs([]);
    addLog(`INIT: Protocol for ${fileToUpload.name}`);

    setTimeout(() => { setUploadStep(2); addLog("KEM: Establishing shared secret..."); }, 1000);
    setTimeout(() => { setUploadStep(3); addLog("HKDF: Deriving AES key..."); }, 2500);

    try {
      const res = await uploadFile(fileToUpload, cryptoMode);
      setTimeout(() => { setUploadStep(4); addLog("AES: Encrypting payload..."); }, 3500);
      setTimeout(() => { setSuccessMode(true); addLog(`SUCCESS: Sealed ID: ${res.data.file_id}`); fetchFiles(); }, 5000);
    } catch (err) {
      setUploadStep(0);
      setCustomAlert({ type: 'error', title: 'Upload Failed', message: 'Server error. Check backend logs.' });
    }
  };

  const handleEncryptedDownload = async (file) => {
    try {
      await downloadEncryptedFile(file.id, file.filename);
    } catch {
      setCustomAlert({ type: 'error', title: 'Error', message: 'Download failed.' });
    }
  };

  const handleDecryptedDownload = async (file) => {
    if (file.mode !== 'hybrid') {
      setCustomAlert({ type: 'error', title: 'Action Denied', message: 'RSA is benchmark only.' });
      return;
    }
    try {
      await downloadDecryptedFile(file.id, file.filename);
    } catch {
      setCustomAlert({ type: 'error', title: 'Integrity Breach', message: 'Signature mismatch.' });
    }
  };

  return (
    <div className="p-8 space-y-6 relative h-full flex flex-col">
      {customAlert && <SciFiAlert {...customAlert} onClose={() => setCustomAlert(null)} />}

      {/* ================= MODAL ================= */}
      {selectedFile && (
        <div className="fixed inset-0 bg-black/90 flex items-center justify-center z-50 backdrop-blur-md">
          <div className="bg-scifi-panel border border-neon-blue w-[720px] p-8 rounded-2xl relative">
            <button onClick={() => setSelectedFile(null)} className="absolute top-4 right-4 text-gray-500 hover:text-white"><X /></button>

            <h2 className="text-2xl font-bold text-white mb-4 flex items-center gap-3">
              <Activity className="text-neon-blue" /> File Security Report
            </h2>

            {/* Tabs */}
            <div className="flex gap-2 mb-4 text-xs">
              <Tab id="overview" active={activeTab} set={setActiveTab} />
              <Tab id="deep" active={activeTab} set={setActiveTab} />
              <Tab id="tree" active={activeTab} set={setActiveTab} />
            </div>

            {/* ================= OVERVIEW ================= */}
            {activeTab === "overview" && (
              <div className="bg-black/50 p-4 rounded-xl border border-gray-800 h-56">
                <Bar
                  data={{
                    labels: ['KEM', 'AES', 'Total'],
                    datasets: [{
                      label: 'Latency (ms)',
                      data: [
                        (selectedFile.metrics?.phase_2?.encap_us || 0) / 1000,
                        selectedFile.metrics?.phase_4?.aes_enc_ms || 0,
                        selectedFile.metrics?.total_ms || 0
                      ],
                      backgroundColor: ['#00ff9d', '#00f3ff', '#ffffff'],
                    }]
                  }}
                  options={{
                    responsive: true,
                    maintainAspectRatio: false,
                    plugins: { legend: { display: false } }
                  }}
                />
              </div>
            )}

            {/* ================= DEEP DIVE ================= */}
            {activeTab === "deep" && (
              <div className="grid grid-cols-2 gap-3 text-xs font-mono">
                <Metric label="File Size" value={selectedFile.metrics?.phase_1?.size_bytes + " B"} />
                <Metric label="Read" value={selectedFile.metrics?.phase_1?.read_ms?.toFixed(2) + " ms"} />
                <Metric label="Encapsulation" value={(selectedFile.metrics?.phase_2?.encap_us || 0) + " us"} />
                <Metric label="Ciphertext" value={selectedFile.metrics?.phase_2?.ciphertext_size + " B"} />
                <Metric label="HKDF" value={(selectedFile.metrics?.phase_3?.hkdf_us || 0) + " us"} />
                <Metric label="AES" value={selectedFile.metrics?.phase_4?.aes_enc_ms?.toFixed(2) + " ms"} />
                <Metric label="Throughput" value={selectedFile.metrics?.phase_4?.throughput_mb_s?.toFixed(2) + " MB/s"} />
                <Metric label="Pack" value={(selectedFile.metrics?.phase_5?.pack_us || 0) + " us"} />
                <Metric label="Total" value={selectedFile.metrics?.total_ms?.toFixed(2) + " ms"} />
              </div>
            )}

            {/* ================= TREE ================= */}
            {activeTab === "tree" && (
              <div className="text-xs font-mono space-y-3 max-h-[350px] overflow-y-auto">
                <TreeNode title="ROOT — Secure Upload">
                  <TreeNode title="Phase 1 — Local Prep">
                    <Leaf label="Size" value={selectedFile.metrics?.phase_1?.size_bytes + " B"} />
                    <Leaf label="Read" value={selectedFile.metrics?.phase_1?.read_ms?.toFixed(2) + " ms"} />
                  </TreeNode>

                  <TreeNode title="Phase 2 — X25519 Agreement">
                    <Leaf label="Encap" value={(selectedFile.metrics?.phase_2?.encap_us || 0) + " us"} />
                    <Leaf label="CT Size" value={selectedFile.metrics?.phase_2?.ciphertext_size + " B"} />
                  </TreeNode>

                  <TreeNode title="Phase 3 — HKDF">
                    <Leaf label="Derive" value={(selectedFile.metrics?.phase_3?.hkdf_us || 0) + " us"} />
                  </TreeNode>

                  <TreeNode title="Phase 4 — AES-GCM">
                    <Leaf label="Encrypt" value={selectedFile.metrics?.phase_4?.aes_enc_ms?.toFixed(2) + " ms"} />
                    <Leaf label="Speed" value={selectedFile.metrics?.phase_4?.throughput_mb_s?.toFixed(2) + " MB/s"} />
                  </TreeNode>

                  <TreeNode title="Phase 5 — Packing">
                    <Leaf label="Pack" value={(selectedFile.metrics?.phase_5?.pack_us || 0) + " us"} />
                  </TreeNode>
                </TreeNode>
              </div>
            )}

            {/* Buttons */}
            <div className="flex justify-end gap-3 mt-6">
              <button
                onClick={async () => {
                  await deleteFile(selectedFile.id);
                  setFiles(prev => prev.filter(f => f.id !== selectedFile.id));
                  setSelectedFile(null);
                }}
                className="px-4 py-2 border border-red-500 text-red-500 rounded hover:bg-red-500/10"
              >
                Delete
              </button>

              <button
                onClick={() => handleEncryptedDownload(selectedFile)}
                className="px-4 py-2 border border-gray-500 text-gray-300 rounded hover:bg-white/10"
              >
                Download Encrypted
              </button>

              <button
                onClick={() => handleDecryptedDownload(selectedFile)}
                className="px-4 py-2 bg-neon-blue text-black font-bold rounded"
              >
                Decrypt & Download
              </button>
            </div>

          </div>
        </div>
      )}

      {/* rest of your dashboard stays SAME */}
    </div>
  );
};

const Tab = ({ id, active, set }) => (
  <button
    onClick={() => set(id)}
    className={`px-3 py-1 rounded capitalize ${active === id ? "bg-neon-blue text-black" : "bg-white/10 text-gray-400"}`}
  >
    {id}
  </button>
);

const Metric = ({ label, value }) => (
  <div className="bg-black/40 border border-gray-800 p-3 rounded flex justify-between">
    <span className="text-gray-400">{label}</span>
    <span className="text-neon-green">{value}</span>
  </div>
);

const TreeNode = ({ title, children }) => (
  <div className="ml-2 border-l border-neon-blue pl-3">
    <div className="text-neon-blue font-bold mb-1">✔ {title}</div>
    {children}
  </div>
);

const Leaf = ({ label, value }) => (
  <div className="flex justify-between text-gray-400 ml-4">
    <span>{label}</span>
    <span className="text-neon-green">{value}</span>
  </div>
);

export default Dashboard;
